from flask import Blueprint, request, jsonify
from app.models.problem import Problem
from app.database import db

problem_controller_bp = Blueprint('problem_controller', __name__)

@problem_controller_bp.route('/problems', methods=['GET'])
def get_problems():
    try:
        problems = Problem.query.all()
        problems_data = [problem.to_dict() for problem in problems]
        return jsonify({'success': True, 'problems': problems_data}), 200
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@problem_controller_bp.route('/problems/<int:problem_id>', methods=['GET'])
def get_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'success': False, 'error': 'Problem not found'}), 404
        return jsonify({'success': True, 'problem': problem.to_dict()}), 200
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@problem_controller_bp.route('/problems', methods=['POST'])
def create_problem():
    try:
        data = request.get_json()
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400

        new_problem = Problem(
            title=data.get('title'),
            description=data.get('description'),
            difficulty=data.get('difficulty')
        )
        db.session.add(new_problem)
        db.session.commit()
        return jsonify({'success': True, 'problem': new_problem.to_dict()}), 201
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@problem_controller_bp.route('/problems/<int:problem_id>', methods=['PUT'])
def update_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'success': False, 'error': 'Problem not found'}), 404

        data = request.get_json()
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'}), 400

        problem.title = data.get('title', problem.title)
        problem.description = data.get('description', problem.description)
        problem.difficulty = data.get('difficulty', problem.difficulty)

        db.session.commit()
        return jsonify({'success': True, 'problem': problem.to_dict()}), 200
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@problem_controller_bp.route('/problems/<int:problem_id>', methods=['DELETE'])
def delete_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'success': False, 'error': 'Problem not found'}), 404

        db.session.delete(problem)
        db.session.commit()
        return jsonify({'success': True, 'message': 'Problem deleted successfully'}), 200
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

def problem_controller():
    return problem_controller_bp

from flask import Blueprint, request, jsonify
from app.models.user import User
from app.database import db

user_controller = Blueprint('user_controller', __name__)

@user_controller.route('/users', methods=['GET'])
def get_users():
    try:
        users = User.query.all()
        users_data = [{'id': user.id, 'username': user.username, 'email': user.email} for user in users]
        return jsonify(users_data), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_controller.route('/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    try:
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        user_data = {'id': user.id, 'username': user.username, 'email': user.email}
        return jsonify(user_data), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_controller.route('/users', methods=['POST'])
def create_user():
    try:
        data = request.get_json()
        username = data.get('username')
        email = data.get('email')
        if not username or not email:
            return jsonify({'error': 'Invalid input'}), 400
        new_user = User(username=username, email=email)
        db.session.add(new_user)
        db.session.commit()
        return jsonify({'message': 'User created successfully', 'id': new_user.id}), 201
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_controller.route('/users/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    try:
        data = request.get_json()
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        username = data.get('username')
        email = data.get('email')
        if username:
            user.username = username
        if email:
            user.email = email
        db.session.commit()
        return jsonify({'message': 'User updated successfully'}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_controller.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    try:
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        db.session.delete(user)
        db.session.commit()
        return jsonify({'message': 'User deleted successfully'}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

from flask import Blueprint, request, jsonify
from app.models.solution import Solution
from app.database import db

solution_controller = Blueprint('solution_controller', __name__)

@solution_controller.route('/solutions', methods=['GET'])
def get_solutions():
    try:
        solutions = Solution.query.all()
        solutions_data = [solution.to_dict() for solution in solutions]
        return jsonify({'solutions': solutions_data}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@solution_controller.route('/solutions/<int:solution_id>', methods=['GET'])
def get_solution(solution_id):
    try:
        solution = Solution.query.get(solution_id)
        if not solution:
            return jsonify({'error': 'Solution not found'}), 404
        return jsonify({'solution': solution.to_dict()}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@solution_controller.route('/solutions', methods=['POST'])
def create_solution():
    try:
        data = request.get_json()
        new_solution = Solution(**data)
        db.session.add(new_solution)
        db.session.commit()
        return jsonify({'message': 'Solution created successfully', 'solution': new_solution.to_dict()}), 201
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@solution_controller.route('/solutions/<int:solution_id>', methods=['PUT'])
def update_solution(solution_id):
    try:
        solution = Solution.query.get(solution_id)
        if not solution:
            return jsonify({'error': 'Solution not found'}), 404
        data = request.get_json()
        for key, value in data.items():
            setattr(solution, key, value)
        db.session.commit()
        return jsonify({'message': 'Solution updated successfully', 'solution': solution.to_dict()}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@solution_controller.route('/solutions/<int:solution_id>', methods=['DELETE'])
def delete_solution(solution_id):
    try:
        solution = Solution.query.get(solution_id)
        if not solution:
            return jsonify({'error': 'Solution not found'}), 404
        db.session.delete(solution)
        db.session.commit()
        return jsonify({'message': 'Solution deleted successfully'}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500
